import type { FinanceDatabase } from "@/lib/interfaces/database";
import { listRecordedOccurrenceKeys } from "@/lib/server/recurring/occurrences";

/** `templateId:month` of the occurrences that already happened, generated by the app or linked to a real entry. */
export async function recurringOccurrences(
  database: FinanceDatabase,
  startMonth: string,
  endMonth: string,
  templateIds: string[],
) {
  return listRecordedOccurrenceKeys(database, templateIds, { startMonth, endMonth });
}
